# Rate limiting de SYN — nftables (por destino, não por origem)
table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;

    # aceita até 2000 SYN/s para o serviço, com rajada de 5000
    tcp flags syn / syn,ack \
      limit rate 2000/second burst 5000 packets accept

    # excedente é descartado antes de tocar a pilha TCP
    tcp flags syn / syn,ack drop

    ct state established,related accept
  }
}

# SYNPROXY — o firewall completa o handshake no lugar do servidor
# e só repassa conexões já validadas
table ip raw {
  chain prerouting {
    type filter hook prerouting priority -300;
    tcp dport 443 tcp flags syn notrack
  }
}
table ip filter {
  chain input {
    tcp dport 443 ct state invalid,untracked \
      synproxy mss 1460 wscale 7 timestamp sack-perm
  }
}

# Ajustes complementares no servidor
net.ipv4.tcp_max_syn_backlog = 8192   # fila maior
net.ipv4.tcp_synack_retries  = 2      # desiste antes do half-open
net.core.somaxconn           = 4096   # fila de accept da aplicação

# Ordem de aplicação sob ataque:
#   1. SYN cookies (imediato, no servidor)
#   2. Rate limit na borda (reduz o que chega)
#   3. Scrubbing do upstream (se saturar o link)
